(function(root){
'use strict';
const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const HEADINGS={'ACTIVITIES THIS WEEK':'Activities this week','BENEFICIARIES REACHED (NUMBERS)':'Beneficiaries reached (numbers)','NEXT WEEK':'Next week','PHOTOS (LIST CAPTIONS)':'Photos (list captions)','ACTIVITIES':'Activities & delivery','ACTIVITIES AND REPORTED COUNTS':'Activities & delivery','CHALLENGES':'Challenges','NEXT STEPS':'Next reporting period','COORDINATOR REVIEW':'Coordinator review notes','REVIEW NOTES':'Coordinator review notes'};
function parse(text){const lines=String(text).replace(/\r\n?/g,'\n').split('\n');const sections=[];const intro=[];let current=null;const evidence=[];
 for(const line of lines){const value=line.trim();if(!value)continue;if(HEADINGS[value]){current={title:HEADINGS[value],review:/REVIEW/.test(value),items:[]};sections.push(current);continue;}if(current){if(/^Source:\s*/i.test(value)){const quote=value.replace(/^Source:\s*/i,'');const item=current.items[current.items.length-1];evidence.push({section:current.title,claim:item?.text||'Source excerpt',quote});if(item)item.reference=evidence.length;}else current.items.push({text:value});}else intro.push(value);}
 const periodLine=intro.find(l=>/^Reporting period:/i.test(l));const org=intro.find(l=>l!=='WEEKLY DONOR REPORT'&&!/^Reporting period:/i.test(l))||'Organisation not provided';
 return{org,period:periodLine?periodLine.replace(/^Reporting period:\s*/i,''):'Reporting period not provided',intro:intro.filter(l=>l!=='WEEKLY DONOR REPORT'&&l!==org&&l!==periodLine),sections,evidence};}
const css=`@page{size:A4;margin:19mm 18mm 18mm;@bottom-left{content:'NGO DONOR REPORTS & DONATION RECEIPTS  /  DONOR REPORT';font:8pt Arial;color:#78827b}@bottom-right{content:counter(page);font:8pt Arial;color:#78827b}}*{box-sizing:border-box}html{background:#e7ebe6}body{margin:0;color:#23372e;font:10.5pt/1.65 Arial,Helvetica,sans-serif;-webkit-print-color-adjust:exact;print-color-adjust:exact}.document{max-width:210mm;margin:24px auto;background:white;padding:19mm 18mm;box-shadow:0 4px 25px #203d2915}.masthead{display:flex;justify-content:space-between;gap:20px;border-top:6px solid #254b3b;padding-top:16px;margin-bottom:30px}.brand{font-size:9pt;letter-spacing:1.4px;font-weight:bold;color:#254b3b}.status{font-size:8pt;letter-spacing:.7px;border:1px solid #d3ded7;padding:4px 9px;color:#53705d;white-space:nowrap}h1{font:700 31pt/1.12 Georgia,serif;letter-spacing:-.5pt;margin:15px 0 10px;color:#203f30}.org{font-size:14pt;font-weight:bold;margin:0 0 7px}.metadata{display:flex;gap:25px;flex-wrap:wrap;background:#f0f4ee;padding:14px 17px;border-left:3px solid #a7b99c;margin:22px 0 28px}.metadata span{display:block;font-size:8pt;letter-spacing:.6px;text-transform:uppercase;color:#70816f}.metadata b{font-size:10.5pt;font-weight:normal}.report-section{margin:24px 0}.section-header{display:flex;align-items:baseline;gap:12px;border-bottom:1px solid #dce4dc;padding-bottom:8px;margin-bottom:14px;break-after:avoid}.section-number{font-size:9pt;color:#8a9a83;letter-spacing:1px}h2{font-size:13pt;line-height:1.35;color:#254b3b;margin:0;font-weight:bold}.report-list{padding:0;list-style:none;margin:0}.report-list li{position:relative;padding:0 0 12px 18px;overflow-wrap:anywhere;orphans:3;widows:3}.report-list li:before{content:'';width:5px;height:5px;background:#a9bc9e;position:absolute;top:8px;left:0;border-radius:50%}.ref{font-size:8pt;color:#71896b;vertical-align:super;padding-left:3px}p{overflow-wrap:anywhere;orphans:3;widows:3}.doc-footer{border-top:1px solid #dce4dc;padding-top:12px;margin-top:28px;font-size:8pt;color:#74816f}.appendix{break-before:page;margin-top:40px}.appendix h1{font-size:23pt}.appendix-intro{color:#70816f;font-size:9pt}.evidence-entry{padding:14px 0;border-bottom:1px solid #e4e9df;overflow-wrap:anywhere;break-inside:avoid}.evidence-entry h3{font-size:10pt;margin:0 0 6px}.evidence-entry p{margin:0;font-size:9pt;color:#5d6f5d}.evidence-entry blockquote{margin:8px 0 0;padding:9px 13px;background:#f5f7f2;border-left:2px solid #a8b99e;font-size:9pt;color:#41543f}.review-box{background:#f5f5ee;border:1px solid #e3e5d7;padding:14px 18px;margin:20px 0}.review-box h2{font-size:11pt;margin-bottom:8px}.review-box p{font-size:9pt;margin:5px 0;color:#626c58}.extra{white-space:pre-wrap}@media print{html{background:white}.document{max-width:none;margin:0;padding:0;box-shadow:none}.appendix{margin-top:0}.status{white-space:normal}}@media screen and (max-width:650px){.document{padding:24px 20px;margin:0;box-shadow:none}h1{font-size:25pt}.masthead{flex-wrap:wrap}.metadata{gap:12px}.status{white-space:normal}}`;
function render(text,{approved=false}={}){const d=parse(text);const normal=d.sections.filter(s=>!s.review);const checks=d.sections.filter(s=>s.review).flatMap(s=>s.items);const sections=normal.length?normal.map((s,i)=>`<section class="report-section"><div class="section-header"><span class="section-number">${String(i+1).padStart(2,'0')}</span><h2>${escape(s.title)}</h2></div><ul class="report-list">${s.items.map(x=>`<li>${escape(x.text)}${x.reference?`<span class="ref">[${x.reference}]</span>`:''}</li>`).join('')}</ul></section>`).join(''):`<section class="report-section"><h2>Report content</h2><p class="extra">${escape(text)}</p></section>`;
const appendix=(d.evidence.length||checks.length)?`<section class="appendix"><div class="brand">APPENDIX / COORDINATOR RECORD</div><h1>Evidence & review notes</h1><p class="appendix-intro">Source excerpts accompany the reviewed report. They support traceability; they do not independently verify the underlying activity.</p>${d.evidence.map((e,i)=>`<div class="evidence-entry"><h3>[${i+1}] ${escape(e.section)}</h3><p>${escape(e.claim)}</p><blockquote>${escape(e.quote)}</blockquote></div>`).join('')}${checks.length?`<div class="review-box"><h2>Coordinator checks</h2>${checks.map(x=>`<p>${escape(x.text)}</p>`).join('')}</div>`:''}</section>`:'';
return`<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${escape(d.org)} — Donor report</title><style>${css}</style></head><body><main class="document"><div class="masthead"><div class="brand">NGO DONOR REPORTS & DONATION RECEIPTS</div><div class="status">${approved?'USER-APPROVED FOR EXPORT':'DRAFT / REVIEW REQUIRED'}</div></div><h1>Weekly donor report</h1><p class="org">${escape(d.org)}</p><div class="metadata"><div><span>Reporting period</span><b>${escape(d.period)}</b></div><div><span>Document type</span><b>Activity & progress report</b></div></div>${d.intro.length?`<p>${d.intro.map(escape).join('<br>')}</p>`:''}${sections}<footer class="doc-footer">Prepared from supplied field notes. Approval is recorded by the app user; this document is not digitally signed or independently audited.</footer>${appendix}</main></body></html>`;}
const api={parse,render};if(typeof module!=='undefined'&&module.exports)module.exports=api;else root.ReportLayout=api;
})(typeof window!=='undefined'?window:globalThis);
